#[test]
fn a_new_import_in_an_edited_file_loads_its_names_on_the_next_request() {
    let (_tmp, root) = two_packages();
    let options = options(&root, true);
    let session = WatchSession::lazy(options.clone());
    drop(session.initialize());
    session.component("A");

    write(
        &root,
        &[(
            "src/A.tsx",
            "import type { AProps } from 'pkg-a';\nimport type { BProps } from 'pkg-b';\n\
             export function A(props: AProps & BProps) { return null; }\n",
        )],
    );
    let update = session.update_file(&root.join("src/A.tsx"));

    assert_eq!(update.updated_keys, ["A"]);
    assert_eq!(session.lazy_stats().unwrap().dependency_files, 1, "an edit loads nothing by itself");
    assert_eq!(prop_names(&session.component("A")), ["a", "b"]);
    assert_eq!(session.lazy_stats().unwrap().dependency_files, 2);
    assert_matches_batch(&session, &options);
}

/// `count` components, each importing its own package, so every request grows the layer until the whole project's
/// names are loaded.
    let recipes = root.join("recipes.ts");

    let edited = crate::pipeline::tests::RECIPES.replace(
        "variant?: \"solid\" | \"outline\" | undefined;",
        "variant?: \"solid\" | \"outline\" | undefined;\n  shape?: \"square\" | undefined;",
    );
    std::fs::write(&recipes, edited).unwrap();
    let update = session.update_file(&recipes);

    assert_eq!(update.updated_keys, vec!["Button".to_owned()]);
    let snapshot = session.snapshot();
    let props: Vec<&String> = snapshot.components["Button"].props.keys().collect();
    assert_eq!(props, ["recipe", "shape", "size", "variant"]);
    assert_eq!(visible(&session.snapshot()), visible(&crate::pipeline::extract(&options)));
}

